setup.src/dag.ts:
export interface TaskSpec {
  readonly id: string;
  readonly duration: number;
  readonly priority: number;
  readonly deps: ReadonlyArray<string>;
}

export interface DagGraph {
  readonly tasks: ReadonlyMap<string, TaskSpec>;
  readonly dependents: ReadonlyMap<string, ReadonlyArray<string>>;
  readonly inDegree: ReadonlyMap<string, number>;
}

export const buildDag = (specs: ReadonlyArray<TaskSpec>): DagGraph => {
  const tasks = new Map<string, TaskSpec>();
  const dependents = new Map<string, Array<string>>();
  const inDegree = new Map<string, number>();

  for (const spec of specs) {
    if (tasks.has(spec.id)) throw new Error(`duplicate task ${spec.id}`);
    tasks.set(spec.id, spec);
    dependents.set(spec.id, []);
    inDegree.set(spec.id, 0);
  }

  for (const spec of specs) {
    for (const dep of spec.deps) {
      if (!tasks.has(dep)) throw new Error(`unknown dependency ${dep}`);
      dependents.get(spec.id)?.push(dep);
      inDegree.set(spec.id, (inDegree.get(spec.id) ?? 0) + 1);
    }
  }

  return { tasks, dependents, inDegree };
};

setup.src/topo.ts:
import type { DagGraph } from "./dag";

export const priorityTopoOrder = (graph: DagGraph): ReadonlyArray<string> => {
  const remaining = new Map(graph.inDegree);
  const ready = [...remaining.entries()]
    .filter(([, deg]) => deg === 0)
    .map(([id]) => id);

  const order: Array<string> = [];
  while (ready.length > 0) {
    const next = ready.shift()!;
    order.push(next);
    for (const child of graph.dependents.get(next) ?? []) {
      const updated = (remaining.get(child) ?? 0) - 1;
      remaining.set(child, updated);
      if (updated === 0) ready.push(child);
    }
  }

  return order;
};

setup.src/scheduler.ts:
import { buildDag, type TaskSpec } from "./dag";
import { priorityTopoOrder } from "./topo";

export interface SchedulePlan {
  readonly order: ReadonlyArray<string>;
  readonly earliestStart: Readonly<Record<string, number>>;
  readonly makespan: number;
}

export const planSchedule = (specs: ReadonlyArray<TaskSpec>): SchedulePlan => {
  const graph = buildDag(specs);
  const order = priorityTopoOrder(graph);
  const earliestStart: Record<string, number> = {};
  let elapsed = 0;

  for (const id of order) {
    const task = graph.tasks.get(id)!;
    earliestStart[id] = elapsed;
    elapsed += task.duration;
  }

  return { order, earliestStart, makespan: elapsed };
};

setup.test/scheduler.test.ts:
import { describe, expect, test } from "bun:test";
import { planSchedule } from "../src/scheduler";

describe("planSchedule", () => {
  test("deduplicates repeated deps, orders ready tasks by priority desc then id asc, and computes critical-path makespan", () => {
    const plan = planSchedule([
      { id: "root", duration: 3, priority: 1, deps: [] },
      { id: "fast-branch", duration: 2, priority: 10, deps: ["root", "root"] },
      { id: "slow-branch", duration: 7, priority: 5, deps: ["root"] },
      { id: "tie-b", duration: 1, priority: 5, deps: ["root"] },
      { id: "join", duration: 4, priority: 20, deps: ["fast-branch", "slow-branch", "tie-b"] },
    ]);

    expect(plan.order).toEqual(["root", "fast-branch", "slow-branch", "tie-b", "join"]);
    expect(plan.earliestStart).toEqual({
      root: 0,
      "fast-branch": 3,
      "slow-branch": 3,
      "tie-b": 3,
      join: 10,
    });
    expect(plan.makespan).toBe(14);
  });

  test("throws on cycles including self-dependencies", () => {
    expect(() =>
      planSchedule([
        { id: "a", duration: 1, priority: 1, deps: ["b"] },
        { id: "b", duration: 1, priority: 1, deps: ["a"] },
      ]),
    ).toThrow(/cycle/i);

    expect(() =>
      planSchedule([{ id: "self", duration: 2, priority: 1, deps: ["self"] }]),
    ).toThrow(/cycle/i);
  });
});
